const assert = require('assert').strict;
const Bottleneck = require('./src/lib');
(async () => {
 const l = new Bottleneck({maxConcurrent: 5});
 let done = 0;
 for (let wave=0; wave<4; wave++) {
  let release, started;
  const ready = new Promise(r=>started=r);
  const blocker = l.schedule({weight:5},()=> {started(); return new Promise(r=>release=r)});
  await ready;
  const order=[];
  const error = new Error('original');
  const low = l.schedule({weight:2,priority:9},()=>{order.push('low'); return 42});
  const high = l.schedule({weight:5,priority:0},async()=>{order.push('high'); assert.equal(await l.running(),5)});
  const fail = l.schedule({weight:3,priority:4},()=>{order.push('fail'); throw error}).catch(e=>assert.equal(e,error));
  const zero = l.schedule({weight:0,priority:4},()=>{order.push('zero')});
  while(l.queued()!==4) await new Promise(r=>setTimeout(r,2));
  release();
  await Promise.all([blocker,high,fail,zero,low.then(v=>assert.equal(v,42))]);
  assert.deepEqual(order,['high','fail','zero','low']);
  done+=15;
  assert.equal(await l.running(),0);
  assert.equal(await l.done(),done);
  assert.equal(l.queued(),0);
 }
 let invoked=false;
 await assert.rejects(l.schedule({weight:6},()=>{invoked=true}));
 assert.equal(invoked,false);
 assert.equal(await l.running(),0);
 console.log('Weighted multi-wave, priority, zero-weight, rejection and overweight checks passed');
})().catch(e=>{console.error(e);process.exitCode=1});
